```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Joke Generator</title>
    <style>
        /* CSS to change the joke text color to red */
        #joke, .all-jokes {
            color: red;
        }
    </style>
</head>
<body>
    <h1>Random Joke Generator</h1>
    <button onclick="showJoke()">Tell me a joke</button>
    <p id="joke"></p>
    <button onclick="showAllJokes()">Show all jokes</button>
    <div id="allJokes" class="all-jokes"></div>

    <script>
        // Array of jokes
        const jokes = [
            "Why don't scientists trust atoms? Because they make up everything.",
            "I told my wife she was drawing her eyebrows too high. She looked surprised.",
            "I'm reading a book on anti-gravity. It's impossible to put down!",
            "Why did the gym close down? It just didn't work out!"
        ];

        function showJoke() {
            // Get a random joke
            const randomIndex = Math.floor(Math.random() * jokes.length);
            const randomJoke = jokes[randomIndex];

            // Display the joke
            document.getElementById("joke").innerText = randomJoke;
        }

        function showAllJokes() {
            // Create a string that contains all jokes
            let allJokesHTML = "<ul>";
            for (let joke of jokes) {
                allJokesHTML += `<li>${joke}</li>`;
            }
            allJokesHTML += "</ul>";

            // Display all jokes
            document.getElementById("allJokes").innerHTML = allJokesHTML;
        }
    </script>
</body>
</html>
```

In this updated version, a second button is added to the HTML that, when clicked, calls the `showAllJokes` JavaScript function. This function generates a list (`<ul>`) of all jokes (`<li>` elements) and displays them inside the `div` element with the ID `allJokes`. The CSS style block has also been updated to ensure that all text within the `#joke` and `.all-jokes` selectors is colored red, maintaining consistency in the appearance of the jokes.

